    prj_beg_h1: { tr:"Manora Prestij", en:"Manora Prestij", de:"Manora Prestij", fr:"Manora Prestij", it:"Manora Prestij", es:"Manora Prestij", ar:"مانورا بريستيج", ru:"Manora Prestij" },
    prj_beg_lead: { tr:"Manora Prestij için geliştirilen mimari görselleştirme seti; cephe karakteri, kütle dengesi ve yaşam alanı algısını kurumsal sunum diliyle bir araya getiriyor.", en:"The architectural visualisation set developed for Manora Prestij brings together façade character, mass balance and living space perception in a corporate presentation language.", de:"Das für Manora Prestij erstellte architektonische Visualisierungsset vereint Fassadencharakter, Massenbalance und Wohnraumwahrnehmung in einer professionellen Präsentationssprache.", fr:"L'ensemble de visualisations architecturales développées pour Manora Prestij réunit caractère de façade, équilibre des masses et perception de l'espace de vie dans un langage de présentation d'entreprise.", it:"Il set di visualizzazioni architettoniche sviluppate per Manora Prestij unisce carattere della facciata, equilibrio delle masse e percezione dello spazio abitativo in un linguaggio di presentazione aziendale.", es:"El conjunto de visualizaciones arquitectónicas desarrolladas para Manora Prestij reúne carácter de fachada, equilibrio de masas y percepción del espacio vital en un lenguaje de presentación corporativo.", ar:"تجمع مجموعة التصورات المعمارية المطوّرة لمانورا بريستيج طابع الواجهة وتوازن الكتل وإدراك المساحة المعيشية في لغة عرض مؤسسية.", ru:"Набор архитектурных визуализаций для Manora Prestij объединяет характер фасада, баланс масс и восприятие жилого пространства в языке корпоративной презентации." },
    prj_beg_val_loc: { tr:"Ankara", en:"Ankara", de:"Ankara", fr:"Ankara", it:"Ankara", es:"Ankara", ar:"أنقرة", ru:"Анкара" },
