    prj_tkc_h1: { tr:"Tek Katlı Çelik Yaşam Yapısı", en:"Single-Storey Steel Living Structure", de:"Eingeschossige Stahlwohnstruktur", fr:"Structure de Vie en Acier de Plain-Pied", it:"Struttura Abitativa in Acciaio a Un Piano", es:"Estructura Habitacional de Acero de Una Planta", ar:"مبنى معيشي فولاذي من طابق واحد", ru:"Одноэтажное стальное жилое строение" },
    prj_tkc_lead: { tr:"Tek katlı hafif çelik sistem taşıyıcı ile tasarlanan yaşam yapısı. Doğaya uyumlu yerleşim ve kontrollü kurulum yapısı ile öne çıkıyor.", en:"A living structure designed with a single-storey light steel system structure. It stands out with its nature-compatible setting and controlled installation structure.", de:"Eine Wohnstruktur, die mit einem eingeschossigen Leichtstahlsystem-Träger konzipiert wurde. Sie besticht durch ihre naturharmonische Lage und kontrollierte Montagestruktur.", fr:"Une structure de vie conçue avec un porteur à système acier léger de plain-pied. Elle se distingue par son implantation en harmonie avec la nature et sa structure de montage contrôlée.", it:"Una struttura abitativa progettata con un sistema portante in acciaio leggero a un piano. Si distingue per l'insediamento in armonia con la natura e la struttura di installazione controllata.", es:"Una estructura habitacional diseñada con un sistema portante de acero ligero de una planta. Destaca por su emplazamiento en armonía con la naturaleza y su estructura de instalación controlada.", ar:"مبنى معيشي مصمم بنظام حامل فولاذي خفيف من طابق واحد. يتميز بموقعه المتناغم مع الطبيعة وبنيته الإنشائية المنضبطة.", ru:"Жилое строение, спроектированное с одноэтажной несущей лёгкой стальной системой. Выделяется гармоничным расположением в природе и контролируемой монтажной структурой." },
    prj_tkc_val_loc: { tr:"İzmir Bölgesi", en:"İzmir Region", de:"Region İzmir", fr:"Région d'İzmir", it:"Regione di İzmir", es:"Región de İzmir", ar:"منطقة إزمير", ru:"Регион Измира" },
