    // ---- proje-beypazari-ankara.html ----
    prj_bey_eyebrow: { tr:"Büyük Ölçekli Yerleşim · Beypazarı / Ankara", en:"Large-Scale Settlement · Beypazarı / Ankara", de:"Großmaßstäbliche Siedlung · Beypazarı / Ankara", fr:"Grand Ensemble Résidentiel · Beypazarı / Ankara", it:"Insediamento di Grande Scala · Beypazarı / Ankara", es:"Urbanización a Gran Escala · Beypazarı / Ankara", ar:"مشروع سكني كبير · بايباذاري / أنقرة", ru:"Крупный жилой проект · Beypazarı / Анкара" },
    prj_bey_h1: { tr:"Beypazarı Ankara Yerleşim Projesi", en:"Beypazarı Ankara Residential Project", de:"Siedlungsprojekt Beypazarı Ankara", fr:"Projet Résidentiel Beypazarı Ankara", it:"Progetto Residenziale Beypazarı Ankara", es:"Proyecto Residencial Beypazarı Ankara", ar:"مشروع سكني بايباذاري أنقرة", ru:"Жилой проект Beypazarı Анкара" },
    prj_bey_lead: { tr:"1.350.000 m² toplam alan üzerinde, ilk etapta 1.200 konut birimi, 50.000 m² AVM ve kapsamlı sosyal tesis alanlarını barındıran karma kullanım yerleşim projesi.", en:"A mixed-use residential project with 1,200 housing units in the first phase, a 50,000 m² shopping centre and comprehensive social facility areas, on a total area of 1,350,000 m².", de:"Ein gemischt genutztes Wohnprojekt mit 1.200 Wohneinheiten in der ersten Phase, einem 50.000 m² Einkaufszentrum und umfangreichen sozialen Einrichtungen auf einer Gesamtfläche von 1.350.000 m².", fr:"Un projet résidentiel à usage mixte avec 1 200 logements en première phase, un centre commercial de 50 000 m² et des équipements sociaux complets, sur une superficie totale de 1 350 000 m².", it:"Un progetto residenziale a uso misto con 1.200 unità abitative nella prima fase, un centro commerciale da 50.000 m² e ampie aree di strutture sociali, su una superficie totale di 1.350.000 m².", es:"Un proyecto residencial de uso mixto con 1.200 unidades de vivienda en la primera fase, un centro comercial de 50.000 m² y extensas áreas de instalaciones sociales, sobre una superficie total de 1.350.000 m².", ar:"مشروع سكني متعدد الاستخدامات يضم 1.200 وحدة سكنية في المرحلة الأولى، ومركزاً تجارياً بمساحة 50.000 م² ومرافق اجتماعية شاملة، على مساحة إجمالية 1.350.000 م².", ru:"Проект жилого комплекса смешанного использования: 1 200 квартир в первой очереди, торговый центр 50 000 м² и обширная социальная инфраструктура на общей площади 1 350 000 м²." },
    prj_bey_tag1: { tr:"Karma Kullanım", en:"Mixed Use", de:"Gemischte Nutzung", fr:"Usage Mixte", it:"Uso Misto", es:"Uso Mixto", ar:"استخدام مختلط", ru:"Смешанное использование" },
    prj_bey_tag2: { tr:"Büyük Ölçek", en:"Large Scale", de:"Großmaßstab", fr:"Grande Échelle", it:"Grande Scala", es:"Gran Escala", ar:"نطاق واسع", ru:"Крупный масштаб" },
    prj_bey_tag3: { tr:"Konut + Ticaret", en:"Housing + Commerce", de:"Wohnen + Handel", fr:"Logement + Commerce", it:"Residenziale + Commerciale", es:"Vivienda + Comercio", ar:"سكن + تجارة", ru:"Жильё + Торговля" },
    prj_bey_summary_p: { tr:"Beypazarı / Ankara'da hayata geçirilen bu referans proje; kapsamlı master plan çalışması, saha koordinasyonu ve karma kullanım programlaması bakımından kurumsal birikimimizin en güçlü göstergelerinden birini oluşturmaktadır.", en:"This reference project realised in Beypazarı / Ankara represents one of the strongest indicators of our corporate experience in terms of comprehensive master planning, site coordination and mixed-use programming.", de:"Dieses Referenzprojekt in Beypazarı / Ankara stellt einen der stärksten Belege unserer Unternehmenskompetenz in den Bereichen umfassende Masterplanung, Baustellenkoordination und gemischte Nutzungsprogrammierung dar.", fr:"Ce projet de référence réalisé à Beypazarı / Ankara constitue l'un des indicateurs les plus forts de notre expérience d'entreprise en termes de planification directrice approfondie, coordination de chantier et programmation à usage mixte.", it:"Questo progetto di riferimento realizzato a Beypazarı / Ankara costituisce uno dei più forti indicatori della nostra esperienza aziendale in termini di pianificazione urbanistica completa, coordinamento del cantiere e programmazione a uso misto.", es:"Este proyecto de referencia realizado en Beypazarı / Ankara constituye uno de los indicadores más sólidos de nuestra experiencia corporativa en términos de planificación directora integral, coordinación de obra y programación de uso mixto.", ar:"يمثّل هذا المشروع المرجعي المُنجَز في بايباذاري / أنقرة أحد أقوى مؤشرات خبرتنا المؤسسية في مجال التخطيط الرئيسي الشامل والتنسيق الميداني والبرمجة المتعددة الاستخدامات.", ru:"Этот референсный проект, реализованный в Beypazarı / Анкара, является одним из наиболее значимых свидетельств нашего корпоративного опыта в области мастер-планирования, координации площадки и программирования смешанного использования." },
