    prj_bey_kv6_val: { tr:"Spor, Peyzaj, Okul Alanları", en:"Sports, Landscape, School Areas", de:"Sport-, Landschafts-, Schulbereiche", fr:"Zones Sport, Paysage, École", it:"Aree Sport, Paesaggio, Scuola", es:"Áreas Deporte, Paisaje, Escuela", ar:"مناطق رياضة وتنسيق حدائق ومدارس", ru:"Спорт, благоустройство, школьные зоны" },
    prj_bey_scope_h: { tr:"Proje Kapsamı", en:"Project Scope", de:"Projektumfang", fr:"Portée du Projet", it:"Ambito del Progetto", es:"Alcance del Proyecto", ar:"نطاق المشروع", ru:"Объём проекта" },
    prj_bey_scope_p: { tr:"Proje; master plan çalışması, altyapı koordinasyonu, konut blok yerleşim planlaması, ticari hacim programlaması ve sosyal donatı tasarımını kapsamakta olup çok disiplinli bir proje yönetimi anlayışıyla hayata geçirilmiştir.", en:"The project encompasses master plan work, infrastructure coordination, residential block layout planning, commercial volume programming and social amenity design, realised through a multidisciplinary project management approach.", de:"Das Projekt umfasst Masterpläne, Infrastrukturkoordination, Wohnblockverteilungsplanung, gewerbliche Volumenprogrammierung und Sozialausstattungsdesign und wurde durch einen multidisziplinären Projektmanagementansatz realisiert.", fr:"Le projet englobe le travail de plan directeur, la coordination des infrastructures, la planification de l'implantation des blocs résidentiels, la programmation du volume commercial et la conception des équipements sociaux, réalisé selon une approche multidisciplinaire de gestion de projet.", it:"Il progetto comprende il lavoro di piano regolatore, la coordinazione delle infrastrutture, la pianificazione del layout dei blocchi residenziali, la programmazione del volume commerciale e la progettazione delle dotazioni sociali, realizzato con un approccio multidisciplinare di gestione del progetto.", es:"El proyecto abarca el trabajo de plan director, la coordinación de infraestructuras, la planificación del trazado de bloques residenciales, la programación del volumen comercial y el diseño de dotaciones sociales, realizado con un enfoque multidisciplinar de gestión de proyectos.", ar:"يشمل المشروع أعمال المخطط الرئيسي وتنسيق البنية التحتية وتخطيط توزيع الكتل السكنية وبرمجة الحجم التجاري وتصميم التجهيزات الاجتماعية، وتمت إحالته وفق نهج إدارة مشاريع متعددة التخصصات.", ru:"Проект охватывает мастер-план, координацию инфраструктуры, планировку жилых блоков, программирование коммерческих объёмов и проектирование социальных объектов, реализованных через мультидисциплинарный подход к управлению проектом." },
    prj_bey_li1: { tr:"Master plan ve parselasyon çalışması", en:"Master plan and parcelling work", de:"Masterplan und Parzellierungsarbeit", fr:"Travail de plan directeur et de lotissement", it:"Lavoro di piano regolatore e parcellizzazione", es:"Trabajo de plan director y parcelación", ar:"أعمال المخطط الرئيسي والتقسيم", ru:"Мастер-план и парцелляция" },
    prj_bey_li2: { tr:"Konut blok tipolojisi ve yerleşim düzeni", en:"Residential block typology and layout", de:"Wohnblocktypologie und Raumanordnung", fr:"Typologie des blocs résidentiels et plan d'implantation", it:"Tipologia dei blocchi residenziali e layout", es:"Tipología de bloques residenciales y distribución", ar:"نمطية الكتل السكنية وتخطيط المواقع", ru:"Типология жилых блоков и их расстановка" },
