    prj_bey_li5: { tr:"Altyapı, yol ağı ve yeşil alan entegrasyonu", en:"Infrastructure, road network and green space integration", de:"Infrastruktur, Straßennetz und Grünflächenintegration", fr:"Intégration des infrastructures, du réseau routier et des espaces verts", it:"Integrazione di infrastrutture, rete stradale e spazi verdi", es:"Integración de infraestructuras, red viaria y espacios verdes", ar:"تكامل البنية التحتية وشبكة الطرق والمساحات الخضراء", ru:"Инфраструктура, дорожная сеть и зелёные зоны" },
    prj_bey_li6: { tr:"İnşaat aşama planı ve taahhüt yönetimi", en:"Construction phasing plan and commitment management", de:"Bauabschnittsplan und Auftragsmanagement", fr:"Plan de phasage de construction et gestion des engagements", it:"Piano di fasi di costruzione e gestione degli impegni", es:"Plan de fases de construcción y gestión de compromisos", ar:"خطة مراحل البناء وإدارة الالتزامات", ru:"Поэтапный план строительства и управление обязательствами" },
