    prj_bey_gallery_h2: { tr:"Beypazarı Ankara Yerleşim Projesi görselleri", en:"Beypazarı Ankara Residential Project visuals", de:"Visuals des Siedlungsprojekts Beypazarı Ankara", fr:"Visuels du projet résidentiel Beypazarı Ankara", it:"Visual del progetto residenziale Beypazarı Ankara", es:"Visuales del Proyecto Residencial Beypazarı Ankara", ar:"مرئيات مشروع سكني بايباذاري أنقرة", ru:"Визуальные материалы жилого проекта Beypazarı Анкара" },

